-- Procede de backend/migrations/001_schema_iniziale.sql.
-- MariaDB 10.6+. Tutte le tabelle principali includono la traccia di audit richiesta.
CREATE TABLE ruoli (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, codice VARCHAR(40) NOT NULL UNIQUE, nome VARCHAR(80) NOT NULL, creato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, modificato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, utente_crea BIGINT UNSIGNED NULL, utente_modifica BIGINT UNSIGNED NULL, stato ENUM('attivo','inattivo') NOT NULL DEFAULT 'attivo');
CREATE TABLE utenti (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, fk_ruolo BIGINT UNSIGNED NOT NULL, nome VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, creato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, modificato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, utente_crea BIGINT UNSIGNED NULL, utente_modifica BIGINT UNSIGNED NULL, stato ENUM('attivo','inattivo') NOT NULL DEFAULT 'attivo', FOREIGN KEY(fk_ruolo) REFERENCES ruoli(id));
CREATE TABLE fornitori (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, codice VARCHAR(30) NOT NULL UNIQUE, nome VARCHAR(120) NOT NULL, creato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, modificato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, utente_crea BIGINT UNSIGNED NULL, utente_modifica BIGINT UNSIGNED NULL, stato ENUM('attivo','inattivo') NOT NULL DEFAULT 'attivo');
CREATE TABLE clienti (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, fk_fornitore BIGINT UNSIGNED NULL, tipo_cliente ENUM('privato','fornitore') NOT NULL, codice VARCHAR(45) NOT NULL UNIQUE, nome VARCHAR(160) NOT NULL, indirizzo VARCHAR(255) NOT NULL, citta VARCHAR(120) NOT NULL, ultimo_manutenzione DATE NULL, creato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, modificato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, utente_crea BIGINT UNSIGNED NULL, utente_modifica BIGINT UNSIGNED NULL, stato ENUM('attivo','inattivo') NOT NULL DEFAULT 'attivo', FOREIGN KEY(fk_fornitore) REFERENCES fornitori(id));
CREATE TABLE marche (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, nome VARCHAR(100) NOT NULL UNIQUE, creato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, modificato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, utente_crea BIGINT UNSIGNED NULL, utente_modifica BIGINT UNSIGNED NULL, stato ENUM('attivo','inattivo') NOT NULL DEFAULT 'attivo');
CREATE TABLE macchine (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, fk_cliente BIGINT UNSIGNED NOT NULL, fk_marca BIGINT UNSIGNED NOT NULL, codice_unico VARCHAR(50) NOT NULL UNIQUE, tipo_macchina ENUM('macchina_caffe','produttore_ghiaccio','lavastoviglie','filtro','addolcitore') NOT NULL, modello VARCHAR(100) NULL, creato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, modificato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, utente_crea BIGINT UNSIGNED NULL, utente_modifica BIGINT UNSIGNED NULL, stato ENUM('attivo','inattivo') NOT NULL DEFAULT 'attivo', FOREIGN KEY(fk_cliente) REFERENCES clienti(id), FOREIGN KEY(fk_marca) REFERENCES marche(id));
CREATE TABLE manutenzioni (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, fk_cliente BIGINT UNSIGNED NULL, fk_tecnico BIGINT UNSIGNED NOT NULL, data DATE NOT NULL, ubicazione ENUM('cliente','magazzino') NOT NULL, note TEXT NULL, esito ENUM('risolto','da_rifare','parziale') NOT NULL DEFAULT 'risolto', creato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, modificato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, utente_crea BIGINT UNSIGNED NULL, utente_modifica BIGINT UNSIGNED NULL, stato ENUM('attivo','inattivo') NOT NULL DEFAULT 'attivo', FOREIGN KEY(fk_cliente) REFERENCES clienti(id), FOREIGN KEY(fk_tecnico) REFERENCES utenti(id));
CREATE TABLE macchine_manutenzioni (fk_macchina BIGINT UNSIGNED NOT NULL, fk_manutenzione BIGINT UNSIGNED NOT NULL, creato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, modificato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, utente_crea BIGINT UNSIGNED NULL, utente_modifica BIGINT UNSIGNED NULL, stato ENUM('attivo','inattivo') NOT NULL DEFAULT 'attivo', PRIMARY KEY(fk_macchina,fk_manutenzione), FOREIGN KEY(fk_macchina) REFERENCES macchine(id), FOREIGN KEY(fk_manutenzione) REFERENCES manutenzioni(id));
CREATE TABLE pezzi (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, fk_marca BIGINT UNSIGNED NULL, nome VARCHAR(150) NOT NULL, codice_unico VARCHAR(60) NOT NULL UNIQUE, tipo_macchina VARCHAR(40) NOT NULL, prezzo DECIMAL(10,2) NOT NULL, intervallo_mesi SMALLINT UNSIGNED NULL, creato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, modificato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, utente_crea BIGINT UNSIGNED NULL, utente_modifica BIGINT UNSIGNED NULL, stato ENUM('attivo','inattivo') NOT NULL DEFAULT 'attivo', FOREIGN KEY(fk_marca) REFERENCES marche(id));
CREATE TABLE tipi_caratteristiche (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, codice_unico VARCHAR(50) NOT NULL UNIQUE, nome VARCHAR(120) NOT NULL, unita_misura VARCHAR(30) NULL, creato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, modificato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, utente_crea BIGINT UNSIGNED NULL, utente_modifica BIGINT UNSIGNED NULL, stato ENUM('attivo','inattivo') NOT NULL DEFAULT 'attivo');
CREATE TABLE pezzi_tipi_caratteristiche (fk_pezzo BIGINT UNSIGNED NOT NULL, fk_tipo_caratteristica BIGINT UNSIGNED NOT NULL, quantita DECIMAL(12,3) NOT NULL, creato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, modificato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, utente_crea BIGINT UNSIGNED NULL, utente_modifica BIGINT UNSIGNED NULL, stato ENUM('attivo','inattivo') NOT NULL DEFAULT 'attivo', PRIMARY KEY(fk_pezzo,fk_tipo_caratteristica), FOREIGN KEY(fk_pezzo) REFERENCES pezzi(id), FOREIGN KEY(fk_tipo_caratteristica) REFERENCES tipi_caratteristiche(id));
CREATE TABLE pezzi_manutenzioni (fk_manutenzione BIGINT UNSIGNED NOT NULL, fk_pezzo BIGINT UNSIGNED NOT NULL, quantita DECIMAL(10,2) NOT NULL DEFAULT 1, prezzo_unitario DECIMAL(10,2) NOT NULL, creato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, modificato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, utente_crea BIGINT UNSIGNED NULL, utente_modifica BIGINT UNSIGNED NULL, stato ENUM('attivo','inattivo') NOT NULL DEFAULT 'attivo', PRIMARY KEY(fk_manutenzione,fk_pezzo), FOREIGN KEY(fk_manutenzione) REFERENCES manutenzioni(id), FOREIGN KEY(fk_pezzo) REFERENCES pezzi(id));
CREATE TABLE boletas (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, fk_cliente BIGINT UNSIGNED NOT NULL, fk_tecnico BIGINT UNSIGNED NOT NULL, codice_boleta VARCHAR(30) NOT NULL UNIQUE, data DATE NOT NULL, prezzo_totale DECIMAL(10,2) NOT NULL DEFAULT 0, creato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, modificato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, utente_crea BIGINT UNSIGNED NULL, utente_modifica BIGINT UNSIGNED NULL, stato ENUM('bozza','emessa','annullata') NOT NULL DEFAULT 'bozza', FOREIGN KEY(fk_cliente) REFERENCES clienti(id), FOREIGN KEY(fk_tecnico) REFERENCES utenti(id));
CREATE TABLE boletas_manutenzioni (fk_boleta BIGINT UNSIGNED NOT NULL, fk_manutenzione BIGINT UNSIGNED NOT NULL, creato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, modificato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, utente_crea BIGINT UNSIGNED NULL, utente_modifica BIGINT UNSIGNED NULL, stato ENUM('attivo','inattivo') NOT NULL DEFAULT 'attivo', PRIMARY KEY(fk_boleta,fk_manutenzione), FOREIGN KEY(fk_boleta) REFERENCES boletas(id), FOREIGN KEY(fk_manutenzione) REFERENCES manutenzioni(id));
CREATE TABLE boletas_macchine (fk_boleta BIGINT UNSIGNED NOT NULL, fk_macchina BIGINT UNSIGNED NOT NULL, creato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, modificato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, utente_crea BIGINT UNSIGNED NULL, utente_modifica BIGINT UNSIGNED NULL, stato ENUM('attivo','inattivo') NOT NULL DEFAULT 'attivo', PRIMARY KEY(fk_boleta,fk_macchina), FOREIGN KEY(fk_boleta) REFERENCES boletas(id), FOREIGN KEY(fk_macchina) REFERENCES macchine(id));
CREATE TABLE boletas_operatori (fk_boleta BIGINT UNSIGNED NOT NULL, fk_operatore BIGINT UNSIGNED NOT NULL, creato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, modificato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, utente_crea BIGINT UNSIGNED NULL, utente_modifica BIGINT UNSIGNED NULL, stato ENUM('attivo','inattivo') NOT NULL DEFAULT 'attivo', PRIMARY KEY(fk_boleta,fk_operatore), FOREIGN KEY(fk_boleta) REFERENCES boletas(id), FOREIGN KEY(fk_operatore) REFERENCES utenti(id));
CREATE TABLE calendario_manutenzioni_macchine (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, fk_macchina BIGINT UNSIGNED NOT NULL, fk_pezzo BIGINT UNSIGNED NULL, fk_manutenzione_origine BIGINT UNSIGNED NULL, frequenza_mesi SMALLINT UNSIGNED NOT NULL, ultima_esecuzione DATE NOT NULL, prossima_manutenzione DATE NOT NULL, stato_calendario ENUM('programmato','eseguito','sospeso') NOT NULL DEFAULT 'programmato', creato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, modificato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, utente_crea BIGINT UNSIGNED NULL, utente_modifica BIGINT UNSIGNED NULL, stato ENUM('attivo','inattivo') NOT NULL DEFAULT 'attivo', FOREIGN KEY(fk_macchina) REFERENCES macchine(id), FOREIGN KEY(fk_pezzo) REFERENCES pezzi(id), FOREIGN KEY(fk_manutenzione_origine) REFERENCES manutenzioni(id));
CREATE TABLE attivita (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, fk_cliente BIGINT UNSIGNED NULL, fk_macchina BIGINT UNSIGNED NULL, fk_assegnato BIGINT UNSIGNED NULL, titolo VARCHAR(180) NOT NULL, scadenza DATE NULL, priorita ENUM('bassa','normale','alta') NOT NULL DEFAULT 'normale', stato_attivita ENUM('aperta','in_corso','completata') NOT NULL DEFAULT 'aperta', creato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, modificato_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, utente_crea BIGINT UNSIGNED NULL, utente_modifica BIGINT UNSIGNED NULL, stato ENUM('attivo','inattivo') NOT NULL DEFAULT 'attivo', FOREIGN KEY(fk_cliente) REFERENCES clienti(id), FOREIGN KEY(fk_macchina) REFERENCES macchine(id), FOREIGN KEY(fk_assegnato) REFERENCES utenti(id));
